static inline uint16_t k1_ws2816_degamma_u16(uint16_t v) {
  if (v == 0) {
    return 0;
  }
  if (v >= 65535) {
    return 65535;
  }
  uint16_t lo = 0;
  uint16_t hi = 255;
  while ((uint16_t)(hi - lo) > 1) {
    uint16_t mid = (uint16_t)((lo + hi) >> 1);
    if (k1_ws2816_degamma_x[mid] <= v) {
      lo = mid;
    } else {
      hi = mid;
    }
  }
  const uint16_t x0 = k1_ws2816_degamma_x[lo];
  const uint16_t x1 = k1_ws2816_degamma_x[hi];
  const uint16_t y0 = k1_ws2816_degamma_y[lo];
  const uint16_t y1 = k1_ws2816_degamma_y[hi];
  if (x1 <= x0) {
    return y0;
  }
  const uint32_t num = (uint32_t)(y1 - y0) * (uint32_t)(v - x0);
  const uint32_t den = (uint32_t)(x1 - x0);
  return (uint16_t)(y0 + (num + (den >> 1)) / den);
}
